<?php
require_once 'config.php';require_once 'includes/auth_services.php';
if(!empty($_GET['error'])){$_SESSION['auth_error']='Google không cho phép đăng nhập.';header('Location: '.$base_url.'dang-nhap');exit;}
$profile=auth_google_profile($conn,(string)($_GET['code']??''),(string)($_GET['state']??''));if(!$profile){$_SESSION['auth_error']='Không thể xác thực tài khoản Google. Vui lòng thử lại.';header('Location: '.$base_url.'dang-nhap');exit;}
$email=mb_strtolower(trim((string)$profile['email']));$googleId=(string)$profile['sub'];$stmt=$conn->prepare('SELECT id,fullname,role,google_id FROM users WHERE email=? OR google_id=? LIMIT 1');$stmt->bind_param('ss',$email,$googleId);$stmt->execute();$user=$stmt->get_result()->fetch_assoc();$stmt->close();
if(!$user){$base=preg_replace('/[^a-z0-9_]/i','',strtok($email,'@'))?:'user';$username=$base;$i=1;while(true){$ck=$conn->prepare('SELECT id FROM users WHERE username=? LIMIT 1');$ck->bind_param('s',$username);$ck->execute();$exists=$ck->get_result()->num_rows>0;$ck->close();if(!$exists)break;$username=$base.$i++;}$fullname=trim((string)($profile['name']??$email));$password=password_hash_secure(bin2hex(random_bytes(16)));$phone='';$role='user';$stmt=$conn->prepare('INSERT INTO users(fullname,username,email,password,google_id,phone,role) VALUES(?,?,?,?,?,?,?)');$stmt->bind_param('sssssss',$fullname,$username,$email,$password,$googleId,$phone,$role);$stmt->execute();$id=$stmt->insert_id;$stmt->close();$user=['id'=>$id,'fullname'=>$fullname,'role'=>'user'];}else{if(empty($user['google_id'])){$stmt=$conn->prepare('UPDATE users SET google_id=? WHERE id=?');$stmt->bind_param('si',$googleId,$user['id']);$stmt->execute();$stmt->close();}}
session_regenerate_id(true);$_SESSION['user_id']=$user['id'];$_SESSION['fullname']=$user['fullname'];$_SESSION['role']=$user['role'];header('Location: '.$base_url);exit;
?>
